import api from '../../services/api';
const BARANGAYS = ['Balingayan', 'Balite', 'Baruyan', 'Batino', 'Bayanan I', 'Bayanan II', 'Biga', 'Bondoc', 'Bucayao', 'Buhuan', 'Bulusan', 'Calero', 'Camansihan', 'Camilmil', 'Canubing I', 'Canubing II', 'Comunal', 'Guinobatan', 'Gulod', 'Gutad', 'Ibaba East', 'Ibaba West', 'Ilaya', 'Lalud', 'Lazareto', 'Libis', 'Lumang Bayan', 'Mahal na Pangalan', 'Maidlang', 'Malad', 'Malamig', 'Managpi', 'Masipit', 'Nag-iba I', 'Nag-iba II', 'Navotas', 'Pachoca', 'Palhi', 'Panggalaan', 'Parang', 'Patas', 'Personas', 'Putingtubig', 'Salong (also known as San Raphael)', 'San Antonio', 'San Vicente Central', 'San Vicente East', 'San Vicente North', 'San Vicente South', 'San Vicente West', 'Santa Cruz', 'Santa Isabel', 'Santa Maria Village', 'Santa Rita', 'Santo Niño', 'Sapul', 'Silonay', 'Suqui', 'Tawagan', 'Tawiran', 'Tibag', 'Wawa'];
export default {
  name: 'StoreLogistics',
  data() {
    return {
      saving: false,
      barangays: BARANGAYS.map(name => ({
        name,
        fee: 0
      }))
    };
  },
  methods: {
    async loadBarangays() {
      try {
        const {
          data
        } = await api.get('/store/delivery-barangays');
        if (Array.isArray(data.barangays) && data.barangays.length) {
          this.barangays = data.barangays.map(row => ({
            name: row.name,
            fee: Number(row.fee || 0)
          }));
        }
      } catch (err) {
        console.error('Failed to load delivery barangays:', err.response?.data?.message);
      }
    },
    async save() {
      this.saving = true;
      try {
        const barangays = {};
        for (const barangay of this.barangays) {
          barangays[barangay.name] = Number(barangay.fee || 0);
        }
        await api.put('/store/delivery-barangays', {
          barangays
        });
        alert('Delivery barangay settings updated');
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to update delivery barangay settings');
      } finally {
        this.saving = false;
      }
    }
  },
  async mounted() {
    await this.loadBarangays();
  }
};
